# Regex patterns for ProofWriter's stylized English
_ENTITY_PAT = re.compile(
    r"\b(?:The\s+)?([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)\b"
    r"(?=\s+(?:is|likes|chases|sees|visits|eats|needs|does))"
